// Optional older-student extension. Separate from the Year 6–8 ten-question game bank.
const SENIOR_BANK={10:[],11:[],12:[]};
const SENIOR_REFERENCE={label:'QCAA · Senior Mathematical Methods overview',url:'https://www.qcaa.qld.edu.au/senior/senior-subjects/syllabuses/mathematics/mathematics-methods',checked:'10 November 2026'};
function addSenior(year,field,prompt,options,why,family=field){if(options.length!==4||new Set(options.map(String)).size!==4)throw Error('Invalid senior question');SENIOR_BANK[year].push({id:year+':'+SENIOR_BANK[year].length,year,field,prompt,options:options.map(String),why,family})}
const SENIOR_CONCEPTS=[
[10,'Mathematics','What are the solutions of x² − 6x + 8 = 0?',['x = 2 or x = 4','x = −2 or x = −4','x = 1 or x = 8','x = 0 or x = 6'],'Factor the quadratic as (x − 2)(x − 4). A product is zero when at least one factor is zero.'],
[10,'Mathematics','A right triangle has legs of 9 cm and 12 cm. What is the hypotenuse?',['15 cm','21 cm','18 cm','13 cm'],'Pythagoras gives c² = 9² + 12² = 225, so c = 15 cm.'],
[10,'Science','In the balanced equation 2H₂ + O₂ → 2H₂O, what is the ratio of hydrogen molecules to oxygen molecules?',['2 : 1','1 : 2','1 : 1','4 : 1'],'The coefficients give the reacting-particle ratio: two hydrogen molecules react with one oxygen molecule.'],
[10,'Biology','For a simplified single-gene trait, two heterozygous parents are Aa and Aa. What is the probability of an aa offspring?',['1/4','1/2','3/4','1'],'The equally likely allele combinations are AA, Aa, aA and aa. One of four is aa; actual traits can have more complex inheritance.'],
[10,'Science','Why can natural selection change a population over generations?',['Heritable variants can affect reproductive success','An individual chooses useful mutations','Every acquired skill is inherited genetically','All variants are equally successful in every environment'],'When heritable variants affect survival or reproduction, their frequencies can change across generations. Selection acts on existing variation.'],
[10,'English','A report says “Everyone supports this policy” after surveying only its organisers. What is the strongest criticism?',['The sample may not represent the wider population','Any survey must be completely false','The policy is proved harmful','The organisers cannot hold opinions'],'A sample drawn only from organisers may systematically differ from the broader population. That limits the generalisation.'],
[10,'English','An article describes a proposal as “a ticking time bomb”. Which effect is most likely?',['It frames the proposal as an urgent threat','It provides a measured probability of failure','It proves an explosion will occur','It makes the language neutral'],'The metaphor evokes imminent danger. It is a framing choice, rather than numerical evidence.'],
[10,'History','Two independent contemporary sources corroborate an event. What does this usually do?',['Strengthen the claim while leaving context and limitations to examine','Prove every detail beyond any possible doubt','Make their authors’ purposes irrelevant','Turn both sources into modern secondary sources'],'Independent corroboration can strengthen a historical claim. Provenance, context and the scope of agreement still matter.'],
[10,'Civics','Why is separation of judicial power valuable in a democracy?',['It helps courts decide cases independently of political pressure','It makes judges responsible for writing every government policy','It removes the need for laws','It guarantees that all decisions satisfy everyone'],'Judicial independence supports impartial application of law and provides a check on misuse of power.'],
[10,'Science','A car speeds up from 4 m/s to 16 m/s in 3 s. What is its average acceleration?',['4 m/s²','12 m/s²','20 m/s²','6 m/s²'],'Average acceleration = change in velocity ÷ time = (16 − 4) ÷ 3 = 4 m/s².'],
[11,'Mathematics','For f(x) = 3x² − 2x, what is f′(x)?',['6x − 2','3x − 2','6x² − 2','6x'],'The power rule gives d(3x²)/dx = 6x and d(−2x)/dx = −2.'],
[11,'Mathematics','If log₁₀(x) = 3, what is x?',['1000','30','100','3'],'A logarithm states an exponent. log₁₀(x) = 3 means 10³ = x.'],
[11,'Mathematics','Events A and B are independent, with P(A) = 0.4 and P(B) = 0.5. What is P(A ∩ B)?',['0.2','0.9','0.1','0.8'],'For independent events, multiply their probabilities: 0.4 × 0.5 = 0.2.'],
[11,'Chemistry','A sample contains 18 g of water. Using molar mass 18 g/mol, how many moles does it contain?',['1 mol','18 mol','324 mol','0.1 mol'],'Amount in moles = mass ÷ molar mass = 18 ÷ 18 = 1 mol.'],
[11,'Biology','Why does a very high temperature often reduce an enzyme’s activity?',['Its three-dimensional structure can change, disrupting the active site','It necessarily becomes a carbohydrate','It starts creating energy from nothing','Its amino acids always become DNA'],'High temperatures can disrupt interactions maintaining an enzyme’s shape. The altered active site may bind substrate less effectively.'],
[11,'Physics','A 2 kg object accelerates at 3 m/s². What net force acts on it?',['6 N','1.5 N','5 N','9 N'],'Newton’s second law gives net force F = ma = 2 × 3 = 6 N.'],
[11,'English','An argument first fairly presents an opposing view, then identifies a weakness. Which technique is being used?',['Concession followed by rebuttal','A guarantee that the opposing view is entirely correct','An unrelated anecdote only','A random change of subject'],'A concession acknowledges part of another position. A rebuttal then challenges its reasoning, evidence or implications.'],
[11,'English','Two texts depict the same event from different social positions. What comparative question is most productive?',['How do perspective and context shape their representations?','Which text has the fewest pages?','Which narrator is automatically correct?','How can all differences be ignored?'],'Comparative analysis examines how values, context and textual choices shape meaning, using evidence from both works.'],
[11,'Economics','A firm’s total revenue rises, but total costs rise by a larger amount. What happens to profit?',['It falls','It must rise','It stays the same','It equals revenue'],'Profit = revenue − total costs. A larger increase in costs than in revenue reduces profit.'],
[11,'Research','Why can a confounding variable undermine a causal interpretation of observational data?',['It may influence both the supposed cause and the outcome','It proves the observed association is imaginary','It guarantees the cause is correct','It eliminates the need for study design'],'A third variable can produce or alter an association. Observational evidence needs careful design and analysis before causal claims are made.'],
[12,'Mathematics','What is the derivative of e^(2x)?',['2e^(2x)','e^(2x)','e^x','2x e^(2x)'],'Use the chain rule: the derivative of e^u is e^u times u′. Here u = 2x and u′ = 2.'],
[12,'Mathematics','Evaluate the definite integral of 2x from x = 0 to x = 3.',['9','6','3','18'],'An antiderivative is x². Evaluating at the bounds gives 3² − 0² = 9.'],
[12,'Mathematics','A binomial model has n = 3 independent trials and success probability 0.5. What is the probability of exactly two successes?',['3/8','1/8','1/2','3/4'],'There are three orders containing exactly two successes. Each has probability (0.5)³ = 1/8, giving 3/8.'],
[12,'Statistics','Which interpretation of a frequentist 95% confidence interval procedure is appropriate?',['About 95% of intervals from repeated samples using the method would contain the fixed population parameter','95% of individual observations must lie in every interval','The parameter changes randomly after every calculation','The sample mean has a 95% chance of being in its own interval'],'Confidence describes the long-run coverage of the interval-producing procedure under its assumptions, rather than the spread of individual observations.'],
[12,'Chemistry','For an equilibrium reaction that releases heat in the forward direction, what is the predicted effect of increasing temperature?',['Equilibrium shifts towards the reactants','Equilibrium must shift towards the products','The equilibrium constant can never change','The reaction necessarily stops completely'],'Adding heat favours the direction that absorbs heat. For an exothermic forward reaction, that is the reverse direction.'],
[12,'Chemistry','If a strong acid solution changes from pH 3 to pH 2, how does hydrogen ion concentration change?',['It increases by a factor of 10','It doubles','It decreases by a factor of 10','It remains identical'],'pH is a base-10 logarithmic measure. A decrease of one pH unit corresponds to a tenfold increase in hydrogen ion activity, approximated by concentration in dilute solutions.'],
[12,'Biology','In a Hardy–Weinberg model, p = 0.7 and q = 0.3. What is the expected heterozygote frequency?',['0.42','0.49','0.09','1.00'],'The model predicts heterozygotes at frequency 2pq = 2 × 0.7 × 0.3 = 0.42, under its assumptions.'],
[12,'Physics','Light of frequency f has photon energy E = hf. What happens if frequency doubles?',['Photon energy doubles','Photon energy halves','Photon energy is unchanged','Photon energy quadruples'],'With Planck’s constant h fixed, energy is proportional to frequency. Doubling f doubles E.'],
[12,'English','Which approach best synthesises two sources that partly disagree?',['Identify their shared claims, evaluate differences and build an evidence-based interpretation','Copy one source and ignore the other','Assume a middle position is always correct','List quotations without relating them'],'Synthesis connects ideas across sources and evaluates tensions. It creates a supported interpretation rather than merely listing separate summaries.'],
[12,'English','A reading offers an interpretation of an ambiguous ending. What most strengthens it?',['A coherent argument supported by textual detail and engagement with alternatives','Claiming that no other reading is possible','Counting words without connecting them to meaning','Relying only on personal preference'],'A strong interpretation links specific textual choices to a coherent argument and can address plausible alternatives.']
];
for(const q of SENIOR_CONCEPTS)addSenior(...q);
function seniorNumeric(year,field,prompt,n,why,family){addSenior(year,field,prompt,[n,n+1,n-1,n+3].map(formatNumber),why,family)}
for(let k=1;k<=40;k++){
 const a=k+2,b=k%6+2;
 seniorNumeric(10,'Mathematics',`Solve x² − ${2*a}x + ${a*a} = 0. What is the repeated root?`,a,`The expression factors as (x − ${a})². Its repeated root is x = ${a}.`,'quadratic-root');
 seniorNumeric(10,'Physics',`An object’s velocity changes from ${a} m/s to ${a+b*4} m/s over 4 seconds. What is its average acceleration in m/s²?`,b,`Average acceleration = (${a+b*4} − ${a}) ÷ 4 = ${b} m/s².`,'acceleration');
 seniorNumeric(11,'Mathematics',`For f(x) = ${a}x² + ${b}x, find f′(2).`,4*a+b,`f′(x) = ${2*a}x + ${b}. At x = 2 this is ${4*a} + ${b} = ${4*a+b}.`,'differentiate-polynomial');
 seniorNumeric(11,'Chemistry',`A substance has molar mass ${a*10} g/mol. What mass in grams contains ${b} mol?`,a*b*10,`Mass = amount × molar mass = ${b} × ${a*10} = ${a*b*10} g.`,'moles-mass');
 seniorNumeric(12,'Mathematics',`Evaluate the definite integral of ${2*a}x from x = 0 to x = ${b}.`,a*b*b,`An antiderivative is ${a}x². The definite integral is ${a} × ${b}² − 0 = ${a*b*b}.`,'definite-integral');
 seniorNumeric(12,'Mathematics',`Let f(x) = (x + ${a})³. What is f′(1)?`,3*(1+a)**2,`By the chain rule, f′(x) = 3(x + ${a})². At x = 1 this is 3 × ${1+a}² = ${3*(1+a)**2}.`,'chain-rule');
}
